package piperplus

// Kaldi fbank + kaiser_best resample parity with torchaudio.
//
// Reads test/fixtures/kaldi_fbank_golden.json (generated by
// test/generate_kaldi_fbank_golden.py with torchaudio, shared with the
// browser's test-kaldi-fbank-golden.js) and checks the front end used for the
// public zs-v1 base's CAM++ embeddings. torchaudio computes in float32 and
// this port in float64, so values are compared with an absolute tolerance.

import (
	"encoding/json"
	"math"
	"os"
	"path/filepath"
	"runtime"
	"testing"
)

type kaldiGolden struct {
	Signal struct {
		DCOffset float64      `json:"dc_offset"`
		Partials [][3]float64 `json:"partials"`
	} `json:"signal"`
	ResampleCases []struct {
		InputRate int       `json:"input_rate"`
		Seconds   float64   `json:"seconds"`
		Output    []float32 `json:"output"`
	} `json:"resample_cases"`
	FbankCase    kaldiFbankCase `json:"fbank_case"`
	PipelineCase kaldiFbankCase `json:"pipeline_case"`
}

type kaldiFbankCase struct {
	InputRate int       `json:"input_rate"`
	Seconds   float64   `json:"seconds"`
	Frames    int       `json:"frames"`
	Values    []float32 `json:"values"`
}

// readRepoFixture unmarshals test/fixtures/<name> from the repository root.
func readRepoFixture(t *testing.T, name string, v any) {
	t.Helper()
	_, filename, _, _ := runtime.Caller(0)
	path := filepath.Join(filepath.Dir(filename), "..", "..", "..", "test", "fixtures", name)
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	if err := json.Unmarshal(data, v); err != nil {
		t.Fatalf("parse %s: %v", path, err)
	}
}

// kaldiTestSignal mirrors test_signal() in the generator: DC offset plus
// sines below Nyquist, computed in float64 and stored as float32.
func kaldiTestSignal(g *kaldiGolden, sampleRate int, seconds float64) []float32 {
	n := int(math.Round(float64(sampleRate) * seconds))
	out := make([]float32, n)
	for i := range out {
		x := g.Signal.DCOffset
		for _, p := range g.Signal.Partials {
			amplitude, freq, phase := p[0], p[1], p[2]
			if freq < float64(sampleRate)/2 {
				x += amplitude * math.Sin(2*math.Pi*freq*float64(i)/float64(sampleRate)+phase)
			}
		}
		out[i] = float32(x)
	}
	return out
}

// Tolerances cover float32 rounding in torchaudio, not algorithm changes
// (same values as test-kaldi-fbank-golden.js): the largest fbank differences
// sit in bins whose log energy is near -16, where float32 FFT cancellation
// dominates; a wrong window, mel scale or preemphasis moves whole frames by
// far more than 1e-2.
const (
	kaldiResampleMaxAbs = 5e-5
	kaldiFbankMaxAbs    = 1e-2
	kaldiFbankMeanAbs   = 1e-3
)

func absDiffs(t *testing.T, actual, expected []float32) (maxDiff, meanDiff float64) {
	t.Helper()
	if len(actual) != len(expected) {
		t.Fatalf("length %d, want %d", len(actual), len(expected))
	}
	sum := 0.0
	for i := range actual {
		d := math.Abs(float64(actual[i]) - float64(expected[i]))
		maxDiff = math.Max(maxDiff, d)
		sum += d
	}
	return maxDiff, sum / float64(len(actual))
}

func assertFbankClose(t *testing.T, feats []float32, c kaldiFbankCase) {
	t.Helper()
	if got := len(feats) / KaldiFbankNumMelBins; got != c.Frames {
		t.Fatalf("frames %d, want %d", got, c.Frames)
	}
	maxDiff, meanDiff := absDiffs(t, feats, c.Values)
	if maxDiff >= kaldiFbankMaxAbs {
		t.Errorf("max abs diff %g", maxDiff)
	}
	if meanDiff >= kaldiFbankMeanAbs {
		t.Errorf("mean abs diff %g", meanDiff)
	}
}

func TestResampleKaiserBest_MatchesTorchaudio(t *testing.T) {
	var g kaldiGolden
	readRepoFixture(t, "kaldi_fbank_golden.json", &g)
	if len(g.ResampleCases) == 0 {
		t.Fatal("no resample cases")
	}
	for _, c := range g.ResampleCases {
		out, err := ResampleKaiserBest(kaldiTestSignal(&g, c.InputRate, c.Seconds), c.InputRate, 16000)
		if err != nil {
			t.Fatal(err)
		}
		if maxDiff, _ := absDiffs(t, out, c.Output); maxDiff >= kaldiResampleMaxAbs {
			t.Errorf("%d Hz -> 16000 Hz: max abs diff %g", c.InputRate, maxDiff)
		}
	}
}

func TestResampleKaiserBest_SameRateAndInvalidRates(t *testing.T) {
	x := []float32{0.1, -0.2, 0.3}
	out, err := ResampleKaiserBest(x, 16000, 16000)
	if err != nil || &out[0] != &x[0] {
		t.Errorf("same rate should return the input, got %v, %v", out, err)
	}
	if _, err := ResampleKaiserBest(x, 0, 16000); err == nil {
		t.Error("expected an error for rate 0")
	}
}

func TestKaldiFbank_MatchesTorchaudio16k(t *testing.T) {
	var g kaldiGolden
	readRepoFixture(t, "kaldi_fbank_golden.json", &g)
	c := g.FbankCase
	assertFbankClose(t, KaldiFbank(kaldiTestSignal(&g, c.InputRate, c.Seconds)), c)
}

func TestKaldiFbank_MatchesTorchaudioAfterResampling(t *testing.T) {
	var g kaldiGolden
	readRepoFixture(t, "kaldi_fbank_golden.json", &g)
	c := g.PipelineCase
	resampled, err := ResampleKaiserBest(kaldiTestSignal(&g, c.InputRate, c.Seconds), c.InputRate, 16000)
	if err != nil {
		t.Fatal(err)
	}
	assertFbankClose(t, KaldiFbank(resampled), c)
}

func TestKaldiFbank_NeedsOneFullWindow(t *testing.T) {
	if n := len(KaldiFbank(make([]float32, 399))); n != 0 {
		t.Errorf("399 samples: %d values, want 0", n)
	}
	if n := len(KaldiFbank(make([]float32, 400))); n != KaldiFbankNumMelBins {
		t.Errorf("400 samples: %d values, want %d", n, KaldiFbankNumMelBins)
	}
}

func TestSubtractBandMeans(t *testing.T) {
	feats := make([]float32, 3*KaldiFbankNumMelBins)
	for i := range feats {
		feats[i] = float32(i)
	}
	subtractBandMeans(feats)
	for m := 0; m < KaldiFbankNumMelBins; m++ {
		sum := 0.0
		for f := 0; f < 3; f++ {
			sum += float64(feats[f*KaldiFbankNumMelBins+m])
		}
		if math.Abs(sum) > 1e-3 {
			t.Errorf("bin %d mean %g", m, sum)
		}
	}
}

func TestSpeakerFrontEndForEmbeddingDim(t *testing.T) {
	cases := map[int]SpeakerFrontEnd{
		192: SpeakerFrontEndKaldiFbank,
		256: SpeakerFrontEndMel,
		0:   SpeakerFrontEndMel,
	}
	for dim, want := range cases {
		if got := SpeakerFrontEndForEmbeddingDim(dim); got != want {
			t.Errorf("dim %d: %v, want %v", dim, got, want)
		}
	}
	if got := staticLastDim([]int64{-1, 192}); got != 192 {
		t.Errorf("staticLastDim([-1 192]) = %d", got)
	}
	if got := staticLastDim([]int64{1, -1}); got != 0 {
		t.Errorf("staticLastDim([1 -1]) = %d", got)
	}
}

func TestL2Normalize(t *testing.T) {
	out, err := l2Normalize([]float32{3, 4})
	if err != nil || math.Abs(float64(out[0])-0.6) > 1e-7 || math.Abs(float64(out[1])-0.8) > 1e-7 {
		t.Errorf("l2Normalize([3 4]) = %v, %v", out, err)
	}
	if _, err := l2Normalize([]float32{0, 0}); err == nil {
		t.Error("expected an error for a zero vector")
	}
	if _, err := l2Normalize([]float32{float32(math.NaN()), 1}); err == nil {
		t.Error("expected an error for NaN")
	}
}
